// Update strategy: network-first for pages + app code (always fresh when online, cache when offline);
// cache-first only for immutable vendor libraries and fonts. A new version activates immediately
// (skipWaiting + clients.claim); the page shows a 'new version' toast and reloads once.
const CF=new RegExp("/(vendor|fonts)/");
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>Promise.all(ASSETS.map(a=>fetch(a,{cache:'no-cache'}).then(r=>{if(r.ok)return c.put(a,r);}).catch(()=>{})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE&&k!==RT).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('message',e=>{if(e.data==='SKIP_WAITING')self.skipWaiting();if(e.data==='VERSION')e.source&&e.source.postMessage({version:CACHE});});
const put=(req,res)=>{if(res&&res.ok&&res.type==='basic'){const c=res.clone();caches.open(CACHE).then(ca=>ca.put(req,c));}return res;};
self.addEventListener('fetch',e=>{
  const r=e.request,u=new URL(r.url);
  if(r.method==='GET'&&CDN.includes(u.hostname)){e.respondWith(caches.open(RT).then(c=>c.match(r).then(m=>m||fetch(r).then(res=>{if(res.ok)c.put(r,res.clone());return res;}))));return;}
  if(r.method!=='GET'||u.origin!==location.origin)return; // AI, Supabase, image and stock-photo API calls go straight to network, never cached
  if(CF.test(u.pathname)){e.respondWith(caches.match(r,{ignoreSearch:true}).then(m=>m||fetch(r).then(res=>put(r,res))));return;}
  const nav=r.mode==='navigate';
  const key=nav?new Request(new URL('./',location.href).href):new Request(u.origin+u.pathname);
  e.respondWith(fetch(nav?u.href:r,{cache:'no-cache',credentials:'same-origin'}).then(res=>put(nav&&u.pathname.endsWith('/')?key:key,res))
    .catch(()=>caches.match(key,{ignoreSearch:true}).then(m=>m||(nav?caches.match('index.html',{ignoreSearch:true}):undefined)||Response.error())));
});
